func checkpointPolicyAllowsGitHook(ctx context.Context, repo *git.Repository) bool {
	policy, err := readLocalCheckpointPolicy(ctx, repo)
	if err != nil {
		warnOrLogCheckpointPolicyReadFailure(ctx, err)
		return false
	}
	if checkpointpolicy.CanSatisfyPolicy(policy) {
		return true
	}
	warnOrLogCheckpointPolicyUpgrade(ctx, policy)
	return false
}

3. cmd/entire/cli/strategy/checkpoint_remote.go:77-128 resolvePushSettings s=57.2 [focus:77]
func resolvePushSettings(ctx context.Context, pushRemoteName string) pushSettings {
	s, err := settings.Load(ctx)
	if err != nil {
		return pushSettings{remote: pushRemoteName}
	}

	ps := pushSettings{
		remote:        pushRemoteName,
		pushDisabled:  s.IsPushSessionsDisabled(),
		primaryIsRefs: primaryIsGitRefs(ctx),
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		return ps
	}
	checkpointURL, enabled, err := remote.PushURL(ctx, pushRemoteName)
	if err != nil {
		logging.Warn(ctx, "checkpoint-remote: could not derive URL from push remote",
			slog.String("remote", pushRemoteName),
			slog.String("repo", config.Repo),
			slog.String("error", err.Error()),
		)
		return ps
	}
	if !enabled || checkpointURL == "" {
		return ps
	}

	ps.checkpointURL = checkpointURL

	// If the v1 checkpoint branch doesn't exist locally, try to fetch it from the URL.
	// This is a one-time operation — once the branch exists locally, subsequent pushes
	// skip the fetch entirely. Only fetch the metadata branch; trails are always pushed
	// to the user's push remote, not the checkpoint remote.
	//
	// Skipped entirely under the git-refs primary backend, where the "one-time"
	// framing does not hold: that backend pushes per-checkpoint refs and never
	// writes the local v1 branch (see prePush), so the branch stays missing
	// forever and every single push would re-pay the fetch. On a large checkpoint
	// remote that is a multi-second stall on each `git push` for a branch this
	// push will not touch.
	if !ps.primaryIsRefs {
		if err := fetchMetadataBranchIfMissing(ctx, checkpointURL); err != nil {
			logging.Warn(ctx, "checkpoint-remote: failed to fetch metadata branch",
				slog.String("error", err.Error()),
			)
		}
	}

	return ps
}

4. cmd/entire/cli/strategy/checkpoint_sync_capture.go:176-207 commitCapturedSyncRemote s=57.2 [focus:176]
func commitCapturedSyncRemote(ctx context.Context, pushRemote string) {
	root, err := capturedSyncRemotesRoot(ctx)
	if err != nil {
		return
	}
	release, err := flock.AcquireIn(root, capturedSyncRemotesLockName)
	if err != nil {
		return
	}
	defer release()

	previouslyElected, ok := captureEligible(ctx, pushRemote)
	if !ok {
		logging.Debug(ctx, "capture no longer eligible after delivery; leaving the election as is",
			slog.String("remote", pushRemote))
		return
	}
	if saveErr := saveCapturedSyncRemote(ctx, pushRemote); saveErr != nil {
		logging.Warn(ctx, "failed to persist captured checkpoint sync remote",
			slog.String("remote", pushRemote),
			slog.String("error", saveErr.Error()))
		return
	}
	// Announced only after the state landed AND the checkpoints did, so the
	// message can claim neither an unpersisted change nor an empty delivery.
	fmt.Fprintf(stderrWriter,
		"[entire] Checkpoints now sync to %q — the remote your branch pushes to. Override with strategy_options.checkpoint_push_remote in .entire/settings.local.json.\n",
		pushRemote)
	logging.Info(ctx, "checkpoint sync remote captured",
		slog.String("remote", pushRemote),
		slog.String("previously_elected", previouslyElected))
}

