116	// cannot run. Proceeding would stamp Entire-OPF-Applied on commits OPF
117	// never saw, and later rewrites would skip them permanently — even
118	// after the user fixes the config. Abort the push with remediation
119	// instead. Two gates enforce this: the decision gate in prePush runs
120	// whenever OPF is enabled, with no knowledge of whether anything is
121	// unpushed, so a misconfigured repo aborts every push — including one
122	// with nothing to rewrite. The rewrite-level gate in
123	// RewriteUnpushedV1WithOPF sits after the no-work early returns and
124	// fires only when commits are unpushed; it deliberately aborts even a
125	// re-parent-only push (every unpushed commit already tagged) rather
126	// than poking a no-new-stamping hole through the invariant.
127	type OPFNoCategoriesError struct{}
128	
129	func (e *OPFNoCategoriesError) Error() string {
130		return "OpenAI Privacy Filter is enabled but no detection category is enabled, " +
131			"so the model scan cannot run; aborting push so unscanned content isn't " +
132			"tagged as OPF-applied. Enable at least one category (e.g. " +
133			`"private_person": true) under redaction.openai_privacy_filter.categories ` +
134			"in .entire/settings.json (or .entire/settings.local.json), set " +
135			"enabled: false to push regex-only content, or set ENTIRE_OPF=no on the " +
136			"push to skip OPF for this push only."
137	}
