140		// bootstrapDefaultLimit caps first-push history rewrites. Picked
141		// to bound worst-case wall-clock at ~50min @ 30s/commit.
142		bootstrapDefaultLimit = 100
143		bootstrapEnvVar       = "ENTIRE_OPF_BOOTSTRAP_LIMIT"
144	)
145	
146	func resolveBootstrapLimit() int {
147		v := strings.TrimSpace(os.Getenv(bootstrapEnvVar))
148		switch {
149		case v == "":
150			return bootstrapDefaultLimit
151		case strings.EqualFold(v, "unlimited"):
152			return math.MaxInt
153		}
154		if n, err := strconv.Atoi(v); err == nil && n > 0 {
155			return n
156		}
157		return bootstrapDefaultLimit
158	}
