453					slog.String("error", err.Error()),
454				)
455				return readV1Tip(repo, plumbing.NewRemoteReferenceName(target, paths.MetadataBranchName))
456			}
457			logging.Warn(ctx, "OPF rewrite: failed to fetch remote v1 from URL; treating push as bootstrap",
458				slog.String("error", err.Error()),
459			)
460			return plumbing.ZeroHash, nil
461		}
