463			if err := repo.Storer.RemoveReference(plumbing.ReferenceName(opfRewriteFetchTmpRef)); err != nil {
464				logging.Debug(ctx, "OPF rewrite: failed to clean up temp ref",
465					slog.String("error", err.Error()),
