139	const (
140		// bootstrapDefaultLimit caps first-push history rewrites. Picked
141		// to bound worst-case wall-clock at ~50min @ 30s/commit.
142		bootstrapDefaultLimit = 100
143		bootstrapEnvVar       = "ENTIRE_OPF_BOOTSTRAP_LIMIT"
144	)
