160	// OPFBatchTooLargeError: a single push has more prose-leaf content
161	// than ENTIRE_OPF_BATCH_LIMIT will allow OPF to chew through in one
162	// inference call. Pushing under the limit yields a single ~10-30s
163	// pause; without the cap, a 100MB-of-prose push could take an hour.
164	//
165	// The user-facing remediation is identical in shape to
166	// BootstrapTooLargeError: bump the limit, push without OPF, or break
167	// the push into smaller pieces.
168	type OPFBatchTooLargeError struct {
169		LeafBytes int
170		Limit     int
171	}
172	
173	func (e *OPFBatchTooLargeError) Error() string {
174		return fmt.Sprintf("OPF would run inference on %d prose-leaf bytes "+
175			"(limit %d). Set ENTIRE_OPF_BATCH_LIMIT=<bytes> or =unlimited to override, "+
176			"or push without OPF (ENTIRE_OPF=no git push) and let a smaller follow-up push run OPF",
177			e.LeafBytes, e.Limit)
178	}
