180	const (
181		// batchDefaultLimit caps the cumulative prose-leaf bytes one push
182		// will hand to OPF. 2 MB at ~5.4s/100KB ≈ ~110s of inference, on
183		// the high end of what's acceptable as a single push pause but
184		// generous enough that any realistic push fits.
185		batchDefaultLimit = 2 * 1024 * 1024
186		batchEnvVar       = "ENTIRE_OPF_BATCH_LIMIT"
187	)
188	
189	func resolveBatchLimit() int {
190		v := strings.TrimSpace(os.Getenv(batchEnvVar))
240	}
