249	// RewriteUnpushedV1WithOPF re-redacts unpushed entire/checkpoints/v1
250	// commits with OPF, builds new commits carrying Entire-OPF-Applied:
251	// true, and CAS-updates the local ref. Idempotent: already-applied
252	// commits are re-parented without re-running OPF.
253	//
254	// Caller checks redact.OPFEnabled() and skips this when OPF is off.
255	// Returns one of {V1DivergedError, BootstrapTooLargeError,
256	// V1RefMovedError, OPFRuntimeFailedError, OPFNoCategoriesError,
257	// OPFBatchTooLargeError, OPFRawBytesTooLargeError} for
258	// privacy-critical failures — the pre-push hook propagates these so
259	// git push aborts.
260	func RewriteUnpushedV1WithOPF(ctx context.Context, repo *git.Repository, target string) (plumbing.Hash, error) {
261		localTip, err := readV1Tip(repo, plumbing.NewBranchReferenceName(paths.MetadataBranchName))
262		if err != nil {
263			return plumbing.ZeroHash, fmt.Errorf("read local v1: %w", err)
264		}
265		if localTip.IsZero() {
266			return plumbing.ZeroHash, nil // no checkpoints yet
267		}
268		remoteTip, err := resolveRemoteV1Tip(ctx, repo, target)
269		if err != nil {
270			return plumbing.ZeroHash, fmt.Errorf("read remote v1: %w", err)
271		}
272	
273		if !remoteTip.IsZero() {
274			mergeBase, mbErr := computeMergeBase(repo, localTip, remoteTip)
275			if mbErr != nil {
276				return plumbing.ZeroHash, fmt.Errorf("compute merge-base: %w", mbErr)
277			}
278			if mergeBase != remoteTip {
279				return plumbing.ZeroHash, &V1DivergedError{Local: localTip, Remote: remoteTip, MergeBase: mergeBase}
280			}
281		}
282	
283		unpushed, err := listUnpushedV1Commits(repo, localTip, remoteTip)
284		if err != nil {
285			return plumbing.ZeroHash, fmt.Errorf("list unpushed v1 commits: %w", err)
286		}
287		if len(unpushed) == 0 {
288			return localTip, nil
289		}
290		if remoteTip.IsZero() {
291			if limit := resolveBootstrapLimit(); len(unpushed) > limit {
292				return plumbing.ZeroHash, &BootstrapTooLargeError{Count: len(unpushed), Limit: limit}
293			}
294		}
295	
296		// Fail-closed defense: enabled-with-no-categories means the model
297		// scan can't run at all. The decision resolution in prePush already
298		// rejects this state before any prompt; this second gate covers
299		// direct callers and sits before the breaker check so the user gets
300		// the config-specific remediation rather than OPFRuntimeFailedError's
301		// "verify your OPF install".
302		if redact.OPFMisconfiguredNoCategories() {
303			return plumbing.ZeroHash, &OPFNoCategoriesError{}
304		}
305	
306		// Fail-closed defense: if OPF is already broken at the start of
307		// this push (an earlier process step tripped the breaker), abort
308		// before tagging any commits as OPF-applied. Without this, the
309		// per-blob fallback inside the no-OPF cases of BatchBytesWithPrivacyFilter
310		// could let regex-only content slip out with the trailer attached.
311		if redact.OPFBreakerTripped() {
312			return plumbing.ZeroHash, &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand()}
313		}
314	
315		// Pass 1: collect every redactable blob from every unpushed commit
316		// that still needs OPF. Already-applied commits get re-parented
317		// later without collecting (their tree stays as-is). We also track
318		// each blob's source commit + tree path so we can route the redacted
319		// bytes back during apply.
320		type pendingCommit struct {
321			commit *object.Commit
322			// blobs and paths are parallel slices; len(paths)==len(blobs).
323			// startIdx is this commit's offset into the global redacted slice.
324			blobs    []redact.NamedBlob
325			paths    []string
326			startIdx int
327		}
328		var globalBlobs []redact.NamedBlob
329		pendings := make([]pendingCommit, 0, len(unpushed))
330		// Bound raw-bytes-in-memory incrementally so a pathological push
331		// (e.g. 5 GiB of pasted dumps) aborts before exhausting the user's
332		// shell RAM. The leaf-byte cap downstream is about inference cost;
333		// this one is about memory ceiling and fires earlier. scaleBatchLimit
334		// saturates at math.MaxInt so "unlimited" actually means unlimited
335		// — without saturation, "unlimited" × 100 overflows int and the cap
336		// trips on every push.
337		rawCap := scaleBatchLimit(resolveBatchLimit(), rawByteCapMultiplier)
338		var rawBytesSoFar int
339		for _, c := range unpushed {
340			pc := pendingCommit{commit: c}
341			if !trailers.HasOPFApplied(c.Message) {
342				tree, err := repo.TreeObject(c.TreeHash)
343				if err != nil {
344					return plumbing.ZeroHash, fmt.Errorf("load tree for %s: %w", c.Hash.String()[:7], err)
345				}
346				pc.startIdx = len(globalBlobs)
347				// Whole-tree redaction: each v1 commit tree is cumulative, so the
348				// newest commit can still carry older shards that were regex-only
349				// before this rewrite. Redacting the whole tree for every unapplied
350				// commit keeps the final rewritten tip from reintroducing an
351				// un-OPF-redacted older shard. collect and apply walk the tree the
352				// same way so the cached keys line up.
353				if err := collectTreeBlobs(repo, tree, "", &pc.blobs, &pc.paths); err != nil {
354					return plumbing.ZeroHash, fmt.Errorf("collect blobs %s: %w", c.Hash.String()[:7], err)
355				}
356				for _, b := range pc.blobs {
357					rawBytesSoFar += len(b.Content)
358				}
359				if rawBytesSoFar > rawCap {
360					return plumbing.ZeroHash, &OPFRawBytesTooLargeError{RawBytes: rawBytesSoFar, Limit: rawCap}
361				}
362				globalBlobs = append(globalBlobs, pc.blobs...)
363			}
364			pendings = append(pendings, pc)
365		}
366	
367		// Pass 2: enforce the leaf-byte cap, then make exactly ONE OPF
368		// shell-out for the whole push. The cap runs before the shell-out
369		// so a too-large push fails fast with a clear remediation message.
370		var globalRedacted [][]byte
371		if len(globalBlobs) > 0 {
372			leafBytes := redact.SumProseLeafBytes(globalBlobs)
373			if limit := resolveBatchLimit(); leafBytes > limit {
374				return plumbing.ZeroHash, &OPFBatchTooLargeError{LeafBytes: leafBytes, Limit: limit}
375			}
376			globalRedacted, err = redact.BatchBytesWithPrivacyFilter(ctx, globalBlobs)
377			if err != nil {
378				// Converge with the up-front gate: the misconfiguration
379				// sentinel must surface config remediation, not "verify
380				// your OPF install".
381				if errors.Is(err, redact.ErrOPFNoEnabledCategories) {
382					return plumbing.ZeroHash, &OPFNoCategoriesError{}
383				}
384				return plumbing.ZeroHash, &OPFRuntimeFailedError{OPFCommand: redact.OPFCommand(), Cause: err}
385			}
386		}
387	
388		// Pass 3: rebuild each commit. For OPF-applied commits, this is
389		// just a re-parent (no tree changes). For unapplied commits, the
390		// per-commit redaction map routes cached bytes by tree path.
391		parent := remoteTip
392		for _, pc := range pendings {
393			var redactedByPath map[string][]byte
394			if len(pc.blobs) > 0 {
395				redactedByPath = make(map[string][]byte, len(pc.blobs))
396				for i, path := range pc.paths {
397					redactedByPath[path] = globalRedacted[pc.startIdx+i]
398				}
399			}
400			newHash, err := rebuildCheckpointCommit(ctx, repo, pc.commit, parent, redactedByPath)
401			if err != nil {
402				return plumbing.ZeroHash, fmt.Errorf("rebuild commit %s: %w", pc.commit.Hash.String()[:7], err)
403			}
404			parent = newHash
405		}
406	
407		if err := atomicSetV1Ref(ctx, repo, localTip, parent); err != nil {
408			return plumbing.ZeroHash, err
409		}
410		return parent, nil
411	}
