413	func readV1Tip(repo *git.Repository, refName plumbing.ReferenceName) (plumbing.Hash, error) {
414		ref, err := repo.Reference(refName, true)
415		if err != nil {
416			if errors.Is(err, plumbing.ErrReferenceNotFound) {
417				return plumbing.ZeroHash, nil
418			}
419			return plumbing.ZeroHash, fmt.Errorf("resolve ref %s: %w", refName, err)
420		}
421		return ref.Hash(), nil
422	}
423	
424	// opfRewriteFetchTmpRef is the temp ref used to stage the URL-fetched
425	// remote v1 tip during OPF rewrite. Cleaned up at the end of each
426	// resolveRemoteV1Tip call so the tracking is invisible to the user.
427	const opfRewriteFetchTmpRef = FetchTmpRefPrefix + "opf-rewrite-v1"
428	
429	// resolveRemoteV1Tip returns the hash of the remote's
430	// entire/checkpoints/v1 tip.
431	//
432	// Fetches the v1 ref from target into a temporary local ref so the
433	// rewrite compares against the current remote tip rather than a stale
434	// remote-tracking ref. target may be either a remote name (e.g. "origin")
435	// or a URL (checkpoint_remote configured). Fetching is especially important
436	// for URL-based remotes, which have no tracking refs locally; otherwise every
437	// push would re-redact the entire history as a "bootstrap."
438	//
439	// Returns ZeroHash with no error when the remote has no v1 yet (genuine
440	// bootstrap case). Fetch failures fall back to ZeroHash + a warning
441	// log; the rewrite then treats the push as bootstrap rather than
442	// blocking the user on a transient network issue.
443	func resolveRemoteV1Tip(ctx context.Context, repo *git.Repository, target string) (plumbing.Hash, error) {
444		srcRef := "refs/heads/" + paths.MetadataBranchName
445		worktreeRoot := ""
446		if wt, wtErr := repo.Worktree(); wtErr == nil {
447			worktreeRoot = wt.Filesystem().Root()
448		}
449		if err := fetchURLIntoTmpRef(ctx, worktreeRoot, target, srcRef, opfRewriteFetchTmpRef, "v1 for OPF rewrite", true, checkpointRemoteFetchTimeout); err != nil {
450			if !remote.IsURL(target) {
451				logging.Warn(ctx, "OPF rewrite: failed to fetch remote v1; using local remote-tracking ref",
452					slog.String("remote", target),
453					slog.String("error", err.Error()),
454				)
455				return readV1Tip(repo, plumbing.NewRemoteReferenceName(target, paths.MetadataBranchName))
456			}
457			logging.Warn(ctx, "OPF rewrite: failed to fetch remote v1 from URL; treating push as bootstrap",
458				slog.String("error", err.Error()),
459			)
460			return plumbing.ZeroHash, nil
461		}
462		defer func() {
463			if err := repo.Storer.RemoveReference(plumbing.ReferenceName(opfRewriteFetchTmpRef)); err != nil {
464				logging.Debug(ctx, "OPF rewrite: failed to clean up temp ref",
465					slog.String("error", err.Error()),
466				)
467			}
468		}()
469		ref, err := repo.Reference(plumbing.ReferenceName(opfRewriteFetchTmpRef), true)
470		if err != nil {
471			if errors.Is(err, plumbing.ErrReferenceNotFound) {
472				return plumbing.ZeroHash, nil
473			}
474			return plumbing.ZeroHash, fmt.Errorf("resolve fetched v1 ref: %w", err)
475		}
476		return ref.Hash(), nil
477	}
