479	// computeMergeBase returns the merge-base commit hash. Multi-base
480	// (criss-cross) and unrelated-histories both return ZeroHash —
481	// caller treats those as diverged.
482	func computeMergeBase(repo *git.Repository, local, remote plumbing.Hash) (plumbing.Hash, error) {
483		lc, err := repo.CommitObject(local)
484		if err != nil {
485			return plumbing.ZeroHash, fmt.Errorf("load local commit: %w", err)
486		}
487		rc, err := repo.CommitObject(remote)
488		if err != nil {
489			return plumbing.ZeroHash, fmt.Errorf("load remote commit: %w", err)
490		}
491		bases, err := lc.MergeBase(rc)
492		if err != nil {
493			return plumbing.ZeroHash, fmt.Errorf("merge-base: %w", err)
494		}
495		if len(bases) != 1 {
496			return plumbing.ZeroHash, nil
497		}
498		return bases[0].Hash, nil
499	}
