501	// listUnpushedV1Commits returns commits reachable from localTip but not
502	// remoteTip, in graph order (oldest-first). Graph order matters more
503	// than timestamp order — commits made in rapid succession can share
504	// Author.When; the parent chain is the unambiguous truth.
505	//
506	// Optimization: the caller (RewriteUnpushedV1WithOPF) has already
507	// validated that remoteTip is the unique merge-base of local and
508	// remote, which means v1 is linear and remoteTip is an ancestor of
509	// localTip. So walking back from localTip, the FIRST commit we hit
510	// whose hash equals remoteTip is the boundary — no need to pre-build
511	// a full remote-reachability set. This drops the cost from
512	// O(local + remote history) to O(unpushed) per call.
513	func listUnpushedV1Commits(repo *git.Repository, localTip, remoteTip plumbing.Hash) ([]*object.Commit, error) {
514		iter, err := repo.Log(&git.LogOptions{From: localTip})
515		if err != nil {
516			return nil, fmt.Errorf("log local tip: %w", err)
517		}
518		defer iter.Close()
519	
520		var unpushed []*object.Commit
521		if walkErr := iter.ForEach(func(c *object.Commit) error {
522			if !remoteTip.IsZero() && c.Hash.Equal(remoteTip) {
523				return errStop
524			}
525			unpushed = append(unpushed, c)
526			return nil
527		}); walkErr != nil && !errors.Is(walkErr, errStop) {
528			return nil, fmt.Errorf("walk local v1 history: %w", walkErr)
529		}
530		// reverse for oldest-first
531		for i, j := 0, len(unpushed)-1; i < j; i, j = i+1, j-1 {
532			unpushed[i], unpushed[j] = unpushed[j], unpushed[i]
533		}
534		return unpushed, nil
535	}

