466	// fetchAndRebaseRefCommon fetches a remote ref and rebases local commits on top
467	// of the remote tip. Since checkpoint shards use unique paths, rebases always
468	// apply cleanly.
469	// The target can be a remote name or a URL.
470	func fetchAndRebaseRefCommon(ctx context.Context, target string, ref plumbing.ReferenceName) error {
471		// No timeout: runs under doPushRef's shared budget.
472		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
473		if err != nil {
474			return fmt.Errorf("resolve fetch target: %w", err)
475		}
476	
477		// Determine fetch refspec. When the resolved fetch target is a URL or the
478		// ref isn't a branch, fetch into a temp ref (no remote-tracking shadow);
479		// otherwise use the standard refs/remotes/<remote>/<branch> destination.
480		var fetchedRefName plumbing.ReferenceName
481		var refSpec string
482		usedTempRef := remote.IsURL(fetchTarget) || !ref.IsBranch()
483		if usedTempRef {
484			tmpRef := "refs/entire-fetch-tmp/" + strings.TrimPrefix(ref.String(), "refs/")
485			refSpec = fmt.Sprintf("+%s:%s", ref.String(), tmpRef)
486			fetchedRefName = plumbing.ReferenceName(tmpRef)
487		} else {
488			refSpec = fmt.Sprintf("+%s:refs/remotes/%s/%s", ref.String(), target, ref.Short())
489			fetchedRefName = plumbing.NewRemoteReferenceName(target, ref.Short())
490		}
