 197	// getAgentHookState probes every hook-supporting agent exactly once, keeping a
 198	// plugin that could not answer distinct from one reporting no hooks.
 199	//
 200	// A binary that fails `info` is never registered, so "unchecked" only ever
 201	// covers a plugin that introduced itself and then failed to answer this.
 202	func getAgentHookState(ctx context.Context) agentHookState {
 203		var state agentHookState
 204		for _, name := range agent.List() {
 205			ag, err := agent.Get(name)
 206			if err != nil {
 207				continue
 208			}
 209			hs, ok := agent.AsHookSupport(ag)
 210			if !ok {
 211				continue
 212			}
 213			installed, err := hs.AreHooksInstalled(ctx)
 214			switch {
 215			case installed:
 216				state.installed = append(state.installed, name)
 217			case err == nil:
 218				// Cleanly reported no hooks.
 219			case ctx.Err() != nil:
 220				// The context died, not the agent. Blaming every plugin on $PATH for
 221				// our own cancellation would turn one Ctrl-C into a page of diagnoses.
 222				logging.Debug(ctx, "hooks-installed check abandoned: context ended",
 223					"agent", string(name))
 224			default:
 225				// Built-in or plugin: if we have a reason, the caller can say so. A
 226				// broken .cursor/hooks.json is as worth reporting as a plugin that
 227				// crashed — what differs is the remedy, not whether to mention it.
 228				state.unchecked = append(state.unchecked, uncheckedAgent{
 229					name:     name,
 230					err:      err,
 231					external: external.IsExternal(ag),
 232				})
 233			}
 234		}
 235		return state
 236	}
