 202	func getAgentHookState(ctx context.Context) agentHookState {
 203		var state agentHookState
 204		for _, name := range agent.List() {
 205			ag, err := agent.Get(name)
 206			if err != nil {
 207				continue
 208			}
 209			hs, ok := agent.AsHookSupport(ag)
 210			if !ok {
 211				continue
 212			}
 213			installed, err := hs.AreHooksInstalled(ctx)
 214			switch {
 215			case installed:
 216				state.installed = append(state.installed, name)
 217			case err == nil:
 218				// Cleanly reported no hooks.
 219			case ctx.Err() != nil:
 220				// The context died, not the agent. Blaming every plugin on $PATH for
 221				// our own cancellation would turn one Ctrl-C into a page of diagnoses.
