153	// copyWorktreeIncludeFiles copies ignored files matching .worktreeinclude
154	// patterns from the main worktree root into a freshly created worktree.
155	// Per-file failures warn and skip; they never fail the checkout.
156	func copyWorktreeIncludeFiles(ctx context.Context, errW io.Writer, root, dest string) error {
157		patterns, err := loadWorktreeIncludePatterns(root)
158		if err != nil {
159			return err
160		}
161		if len(patterns) == 0 {
162			return nil
163		}
164		ignored, err := listIgnoredFiles(ctx, root)
165		if err != nil {
166			return err
167		}
168		matches := matchIncludePatterns(patterns, ignored)
169		if len(matches) == 0 {
170			return nil
171		}
172		// dest is a fresh checkout of the trail branch, whose content the invoking
173		// user did not author. os.Root confines writes to dest even if the branch
174		// contains a tracked symlinked directory pointing outside it.
175		//
176		// The SOURCE gets a root too. rel comes from `git ls-files --ignored`, so it
177		// is a name the checkout chose rather than one Entire did, and it is read
178		// with the same argument that justifies confining the write.
179		srcRoot, err := worktreedir.OpenAt(root)
180		if err != nil {
181			return fmt.Errorf("failed to open source worktree root: %w", err)
182		}
183		destRoot, err := worktreedir.OpenAt(dest)
184		if err != nil {
185			return fmt.Errorf("failed to open worktree root: %w", err)
186		}
187		for _, rel := range matches {
188			if err := copyIncludedFile(srcRoot, destRoot, rel); err != nil {
189				fmt.Fprintf(errW, "warning: skipped %s: %v\n", filepath.ToSlash(rel), err)
190			}
191		}
192		return nil
193	}
194	
195	// loadWorktreeIncludePatterns reads .worktreeinclude from root. A missing
196	// file means nothing gets copied. Lines are gitignore-style patterns; blank
197	// lines and #-comments are skipped.
198	func loadWorktreeIncludePatterns(root string) ([]string, error) {
199		wt, err := worktreedir.OpenAt(root)
200		if err != nil {
201			return nil, fmt.Errorf("failed to open worktree root: %w", err)
202		}
203		data, err := osroot.ReadFileNoFollow(wt, worktreeIncludeFile)
204		if errors.Is(err, fs.ErrNotExist) {
205			return nil, nil
206		}
207		if err != nil {
208			return nil, fmt.Errorf("failed to read %s: %w", worktreeIncludeFile, err)
209		}
210		var patterns []string
211		for raw := range strings.SplitSeq(string(data), "\n") {
212			line := strings.TrimRight(raw, "\r")
213			if strings.TrimSpace(line) == "" || strings.HasPrefix(line, "#") {
214				continue
215			}
216			patterns = append(patterns, line)
217		}
218		return patterns, nil
219	}
