123	// FetchTmpRefPrefix is the namespace for temporary refs used by fetch helpers
124	// to land a fetched hash before safely promoting it to a final ref (via
125	// PromoteTmpRefSafely). Prefer using the named constants below when possible.
126	const FetchTmpRefPrefix = "refs/entire-fetch-tmp/"
127	
128	// PromoteTmpRefSafely reads tmpRefName (the ref a fetch just landed into),
129	// advances destRefName to its hash via SafelyAdvanceLocalRef, then removes
130	// the tmp ref. The cleanup is deferred so the tmp ref is reaped even when
131	// the advance fails.
132	//
133	// label is a short human-readable name used in error messages. Typical use:
134	//
135	//	// fetch with refspec "+<src>:<tmpRefName>"
136	//	refs := checkpoint.ResolveRefs(ctx)
137	//	return PromoteTmpRefSafely(ctx, tmpRefName, refs.Primary, refs.Primary.Short())
138	func PromoteTmpRefSafely(ctx context.Context, tmpRefName, destRefName plumbing.ReferenceName, label string) error {
139		repo, err := OpenRepository(ctx)
140		if err != nil {
141			return fmt.Errorf("failed to open repository for %s promote: %w", label, err)
142		}
143		defer repo.Close()
144		defer func() { _ = repo.Storer.RemoveReference(tmpRefName) }() //nolint:errcheck // cleanup is best-effort
145	
146		tmpRef, err := repo.Reference(tmpRefName, true)
147		if err != nil {
148			return fmt.Errorf("%s not found after fetch (tmp ref %s missing): %w", label, tmpRefName, err)
149		}
150		if err := SafelyAdvanceLocalRef(ctx, repo, destRefName, tmpRef.Hash()); err != nil {
151			return fmt.Errorf("failed to advance local %s: %w", label, err)
152		}
153		return nil
154	}
155	
156	// SafelyAdvanceLocalRef updates localRefName to include targetHash without
157	// dropping local-only commits. Missing and behind refs advance to targetHash;
158	// already-current or locally-ahead refs are left unchanged; diverged refs replay
159	// commits after the merge-base onto targetHash and move localRefName to the
160	// replayed tip. If there is no merge-base and the reachable histories are
161	// complete, the full local chain is replayed.
162	func SafelyAdvanceLocalRef(ctx context.Context, repo *git.Repository, localRefName plumbing.ReferenceName, targetHash plumbing.Hash) error {
163		currentLocal, localErr := repo.Reference(localRefName, true)
164		if localErr != nil {
165			if !errors.Is(localErr, plumbing.ErrReferenceNotFound) {
166				return fmt.Errorf("failed to read local ref %s: %w", localRefName, localErr)
167			}
168			return setRefHash(repo, localRefName, targetHash)
169		}
170	
171		localHash := currentLocal.Hash()
172		if localHash == targetHash {
173			return nil
174		}
175	
176		repoPath, err := getRepoPath(repo)
177		if err != nil {
178			return fmt.Errorf("failed to get repo path: %w", err)
179		}
180	
181		mergeBase, err := getMergeBase(ctx, repoPath, localHash.String(), targetHash.String())
182		if errors.Is(err, errNoMergeBase) {
183			shallow, shallowErr := hasReachableShallowBoundary(ctx, repo, repoPath, localHash.String(), targetHash.String())
184			if shallowErr != nil {
185				return fmt.Errorf("failed to check shallow history for %s: %w", localRefName, shallowErr)
186			}
187			if shallow {
188				return fmt.Errorf("no merge base for %s, and reachable shallow history prevents proving refs are disconnected; run 'entire doctor' or 'git fetch --unshallow' and try again", localRefName)
189			}
190			return replayDisconnectedLocalRef(ctx, repo, repoPath, localRefName, localHash, targetHash)
191		}
192		if err != nil {
193			return fmt.Errorf("failed to find merge base for %s: %w", localRefName, err)
194		}
195		if mergeBase == targetHash {
196			return nil
197		}
198		if mergeBase == localHash {
199			return setRefHash(repo, localRefName, targetHash)
200		}
201	
202		return replayLocalRefFromBase(ctx, repo, repoPath, localRefName, localHash, targetHash, mergeBase)
203	}
