205	func replayLocalRefFromBase(ctx context.Context, repo *git.Repository, repoPath string, localRefName plumbing.ReferenceName, localHash, targetHash, baseHash plumbing.Hash) error {
206		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localHash, baseHash)
207		if err != nil {
