209		}
210		shallow, err := loadShallowHashes(ctx, repoPath)
211		if err != nil {
212			return fmt.Errorf("failed to load shallow boundaries for %s: %w", localRefName, err)
213		}
214		return replayLocalCommits(ctx, repo, "diverged", localRefName, localHash, targetHash, localCommits, shallow)
215	}
