217	func replayDisconnectedLocalRef(ctx context.Context, repo *git.Repository, repoPath string, localRefName plumbing.ReferenceName, localHash, targetHash plumbing.Hash) error {
218		shallow, err := loadShallowHashes(ctx, repoPath)
219		if err != nil {
