  1844	func IsSetUpAndEnabled(ctx context.Context) bool {
  1845		if !IsSetUpAny(ctx) {
  1846			return false
  1847		}
  1848		s, err := Load(ctx)
  1849		if err != nil {
  1850			return false
  1851		}
  1852		return s.Enabled
  1853	}
