		return plumbing.ZeroHash, fmt.Errorf("load tree %s: %w", hash, err)
	}
	entries := make([]object.TreeEntry, 0, len(tree.Entries))
	changed := false
	for _, e := range tree.Entries {
		entryPath := e.Name
