func runStatusJSON(ctx context.Context, w io.Writer) error {
	writeJSON := func(v statusJSON) error {
		return json.NewEncoder(w).Encode(v)
	}

	if _, err := paths.WorktreeRoot(ctx); err != nil {
		return writeJSON(statusJSON{Error: "not a git repository"})
	}

	projectExists, localExists, presenceErr := settings.FilesPresent(ctx)
	if presenceErr != nil {
		return writeJSON(statusJSON{Error: presenceErr.Error()})
	}

	if !projectExists && !localExists {
		return writeJSON(statusJSON{Error: "not set up"})
	}

	s, err := LoadEntireSettings(ctx)
	if err != nil {
		return writeJSON(statusJSON{Error: fmt.Sprintf("failed to load settings: %v", err)})
	}

	result := statusJSON{
		Enabled:        s.Enabled,
		Agents:         []string{},
		ActiveSessions: []sessionBriefJSON{},
		AgentHelp:      agentHelpCommand,
	}

	if s.Enabled {
		if names := InstalledAgentDisplayNames(ctx); len(names) > 0 {
			result.Agents = names
		}

		result.SecretScanners = nonDefaultSecretScanners(s)

		for _, name := range OutdatedHookAgents(ctx) {
			result.HooksOutdated = append(result.HooksOutdated, string(name))
		}
		result.CodexHooks = codexHooksStatusFromIssue(inspectCodexHookIssue(ctx))

		// Same computation as the text path (writeCheckpointSyncLines);
		// empty fields drop out via omitempty when nothing resolved.
		syncInfo := computeCheckpointSyncInfo(ctx, s)

	}
	return confirmed, nil
}

// checkGitHooks reports whether Entire's git hooks are installed and current,
// and offers to reinstall them when they are not.
//
// This is the one hook surface a user cannot see going wrong. Agent hook configs
// are committed files that turn up in a diff; .git/hooks is per-clone and
// untracked, so pulling a release that changes hook generation never touches it.
// A hook left by the removed local-dev mode still carries Entire's marker, so it
// looks installed while naming a launcher inside the working tree that no longer
// exists — and because that shape got no availability guard while pre-push
// deliberately propagates exit codes, the symptom a user actually sees is `git
// push` being rejected.
//
// Unlike the agent hook checks this one repairs rather than only warning: the
// reinstall is content-idempotent, backs up any foreign hook it displaces, and
// writes exactly what the next turn-start would write anyway. Someone reaching
// for doctor after a rejected push wants to be unblocked, not handed a second
// command to run.
func checkGitHooks(cmd *cobra.Command, force bool) error {
	ctx := cmd.Context()
	w := cmd.OutOrStdout()

	switch strategy.CheckGitHookState(ctx) {
	case strategy.GitHooksCurrent:
		fmt.Fprintln(w, "✓ Git hooks: OK")
		return nil

	case strategy.GitHooksAbsent:
		// Missing hooks are only a problem where Entire was actually set up.
		// doctor runs in any git repo, so treating this as actionable would let
		// `entire doctor --force` install hooks into — and back up the existing
		// hooks of — a repo that never opted in. That is the loudest possible
		// surprise from a diagnostic command. The sibling checks already hold this
		// line: checkHookDrift stays silent on HooksAbsent, and
		// checkCodexHookTrust returns early when there is no codex hooks file.
		//
		// IsSetUpAny rather than IsSetUpAndEnabled: a repo that ran `entire
		// disable` still wants working hooks, because the hooks themselves are
		// what no-op while disabled.
		if !settings.IsSetUpAny(ctx) {
			return nil
		}
		fmt.Fprintln(w, "Git hooks: NOT INSTALLED")
		fmt.Fprintln(w, "  Commits in this repository are not captured as checkpoints.")

	case strategy.GitHooksOutdated:
		// Actionable whatever the settings say: a hook carrying Entire's marker
		// means this repo opted in at some point, and a stale one is actively
		// broken rather than merely missing.
		fmt.Fprintln(w, "Git hooks: OUT OF DATE")
		fmt.Fprintln(w, "  A hook still runs Entire from the working tree instead of the installed")
		fmt.Fprintln(w, "  binary. This can reject `git push`, because the path it names is gone.")
	}
	fmt.Fprintln(w, "  Fix: reinstall the managed git hooks (any non-Entire hook is backed up).")

	if !force {
		// Degrade to warn-only when there is nobody to ask. An agent or CI run
		// must not be blocked on a prompt, and rewriting a repo's hooks
		// unasked is worse than naming the command that does it.
		if !interactive.CanPromptInteractively() {
			fmt.Fprintln(w, "  Run `entire doctor --force` to apply it.")
			return nil
		}
		proceed, promptErr := confirmDoctorFix(ctx, w, "Reinstall Entire git hooks?")
		if promptErr != nil {
			return promptErr
		}
		if !proceed {
			return nil
		}
	}

	if _, err := strategy.ReinstallGitHooks(ctx); err != nil {
		return fmt.Errorf("failed to reinstall git hooks: %w", err)
	}
	fmt.Fprintln(w, "  ✓ Fixed: git hooks reinstalled")
	return nil
}
	HooksCurrent = agent.HooksCurrent
	// HooksOutdated means the installed hooks are stale.
	// Fix: `entire enable --force`.
	HooksOutdated = agent.HooksOutdated
)

// CheckHookConfig satisfies agent.HookFreshness by delegating to the
// package-level check, which predates the interface and is still called
// directly by tests.
func (c *ClaudeCodeAgent) CheckHookConfig(ctx context.Context) agent.HookConfigState {
	return CheckHookConfig(ctx)
}

// CheckHookConfig reports whether Entire's Claude Code hooks are absent,
// current, or outdated. It is a read-only diagnostic used by `entire status`
// and `entire doctor`; it never modifies settings. Outdated is detected on the
// positive spec: Entire is installed (Stop hook present) yet one of the current
// tool-use matchers does not carry its Entire hook.
func CheckHookConfig(ctx context.Context) HookConfigState {
	settings, err := loadClaudeSettings(ctx)
	// An unreadable or malformed settings file collapses to HooksAbsent
	// deliberately. This is a coarse three-state diagnostic for `entire status`
	// and `entire doctor`, and no caller here acts on "could not tell" —
	// AreHooksInstalled is the API that propagates that distinction to callers
	// which must (e.g. uninstall deciding whether hooks can be left alone).
	// loadClaudeSettings has already logged the failure.
	if err != nil || !hasEntireHook(settings.Hooks.Stop) {
		return HooksAbsent
	}
	subagentTools := splitMatcherTools(subagentToolMatcher)
	taskTools := splitMatcherTools(taskToolMatcher)
	if !hasEntireHookCoveringTools(settings.Hooks.PreToolUse, subagentTools) ||
		!hasEntireHookCoveringTools(settings.Hooks.PostToolUse, subagentTools) ||
		!hasEntireHookCoveringTools(settings.Hooks.PostToolUse, taskTools) ||
		!hasEntireHook(settings.Hooks.SubagentStop) {
		return HooksOutdated
	}
	return HooksCurrent
}

