+	t.Parallel()
+	porcelain := []byte("worktree /repo/current\x00HEAD abc\x00\x00" +
+		"worktree /repo/ready\x00HEAD def\x00\x00" +
+		"worktree /repo/gone\x00HEAD 123\x00prunable gitdir file points to non-existent location\x00\x00")
