package strategy

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os/exec"
	"path"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	git "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

const metadataCleanupFetchTmpRef = "refs/entire-tmp/metadata-cleanup-v1"

func prepareOversizedV1ForPush(ctx context.Context, repo *git.Repository, target string, threshold int64) error {
	localTip, err := readV1Tip(repo, plumbing.NewBranchReferenceName(paths.MetadataBranchName))
	if err != nil {
		return fmt.Errorf("read local checkpoint history: %w", err)
	}
	if localTip.IsZero() {
		return nil
	}
	hasOversizedHistory, err := tipHasOversizedMetadata(ctx, repo, localTip, threshold)
	if err != nil {
		return err
	}
	if !hasOversizedHistory {
		return nil
	}
	remoteTip, err := fetchV1TipForMetadataCleanup(ctx, repo, target)
	if err != nil {
		return err
	}
	_, _, err = reconcileOversizedV1ForPush(ctx, repo, localTip, remoteTip, threshold)
	return err
}

func tipHasOversizedMetadata(ctx context.Context, repo *git.Repository, tip plumbing.Hash, threshold int64) (bool, error) {
	commit, err := repo.CommitObject(tip)
	if err != nil {
		return false, fmt.Errorf("load checkpoint tip %s: %w", tip, err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return false, fmt.Errorf("load checkpoint tip tree: %w", err)
	}
	files := tree.Files()
	defer files.Close()
	found := false
	walkErr := files.ForEach(func(file *object.File) error {
		if err := ctx.Err(); err != nil {
			return fmt.Errorf("scan checkpoint tip metadata: %w", err)
		}
		if path.Base(file.Name) != paths.MetadataFileName {
			return nil
		}
		blob, err := repo.BlobObject(file.Hash)
		if err != nil {
			return fmt.Errorf("load metadata blob %s at %s: %w", file.Hash, file.Name, err)
		}
		if blob.Size > threshold {
			found = true
			return errStop
		}
		return nil
	})
	if walkErr != nil && !errors.Is(walkErr, errStop) {
		return false, fmt.Errorf("walk checkpoint tip tree: %w", walkErr)
	}
	return found, nil
}

func fetchV1TipForMetadataCleanup(ctx context.Context, repo *git.Repository, target string) (plumbing.Hash, error) {
	worktree, err := repo.Worktree()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("resolve worktree for checkpoint metadata probe: %w", err)
	}
	ref := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	probeCtx, cancel := context.WithTimeout(ctx, checkpointRemoteFetchTimeout)
	defer cancel()
	out, err := remote.LsRemoteInDir(probeCtx, worktree.Filesystem().Root(), target, ref.String())
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("probe %s on %s: %w", ref, remote.RedactURLOrPath(target), err)
	}
	if len(bytes.TrimSpace(out)) == 0 {
		return plumbing.ZeroHash, nil
	}

	if err := fetchURLIntoTmpRef(
		ctx,
		worktree.Filesystem().Root(),
		target,
		ref.String(),
		metadataCleanupFetchTmpRef,
		"v1 for metadata cleanup",
		true,
		checkpointRemoteFetchTimeout,
	); err != nil {
		return plumbing.ZeroHash, err
	}
	defer func() {
		_ = repo.Storer.RemoveReference(plumbing.ReferenceName(metadataCleanupFetchTmpRef)) //nolint:errcheck // cleanup is best-effort
	}()
	fetched, err := repo.Reference(plumbing.ReferenceName(metadataCleanupFetchTmpRef), true)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("read fetched checkpoint history: %w", err)
	}
	return fetched.Hash(), nil
}

// reconcileOversizedV1ForPush replaces stale oversized local history only when
// a repaired remote proves where the shared checkpoint content ends.
func reconcileOversizedV1ForPush(
	ctx context.Context,
	repo *git.Repository,
	observedLocalTip, remoteTip plumbing.Hash,
	threshold int64,
) (plumbing.Hash, bool, error) {
	if observedLocalTip.IsZero() {
		return observedLocalTip, false, nil
	}

	mergeBase := plumbing.ZeroHash
	if !remoteTip.IsZero() {
		var err error
		mergeBase, err = computeMergeBase(repo, observedLocalTip, remoteTip)
		if err != nil {
			return plumbing.ZeroHash, false, fmt.Errorf("compute original merge-base: %w", err)
		}
		if mergeBase.IsZero() {
			return observedLocalTip, false, nil
		}
	}
	hasOversizedLocalHistory, err := hasOversizedMetadataIntroducedSince(
		ctx, repo, observedLocalTip, mergeBase, threshold,
	)
	if err != nil {
		return plumbing.ZeroHash, false, err
	}
	if !hasOversizedLocalHistory {
		return observedLocalTip, false, nil
	}

	rewriter := newMetadataRewriter(ctx, repo, threshold)
	rewrittenTip, err := rewriter.rewriteHistory(observedLocalTip)
	if err != nil {
		return plumbing.ZeroHash, false, fmt.Errorf("rewrite oversized local metadata: %w", err)
	}
	if rewriter.commitsRewritten == 0 {
		return observedLocalTip, false, nil
	}
	if remoteTip.IsZero() {
		if err := atomicSetV1Ref(ctx, repo, observedLocalTip, rewrittenTip); err != nil {
			return plumbing.ZeroHash, false, err
		}
		return rewrittenTip, true, nil
	}

	rewrittenBoundary, originalBoundary, found, err := findSharedRewrittenTree(
		ctx, repo, rewrittenTip, remoteTip, rewriter.commits,
	)
	if err != nil {
		return plumbing.ZeroHash, false, err
	}
	if !found {
		return observedLocalTip, false, nil
	}

	safe, err := boundaryAtOrAfterMergeBase(repo, mergeBase, originalBoundary)
	if err != nil {
		return plumbing.ZeroHash, false, err
	}
	if !safe {
		return observedLocalTip, false, nil
	}

	repoPath, err := getRepoPath(repo)
	if err != nil {
		return plumbing.ZeroHash, false, fmt.Errorf("get repository path: %w", err)
	}
	localOnly, err := collectCommitsSince(ctx, repo, repoPath, rewrittenTip, rewrittenBoundary)
	if err != nil {
		return plumbing.ZeroHash, false, fmt.Errorf("collect local checkpoints after repaired boundary: %w", err)
	}

	newTip := remoteTip
	if len(localOnly) > 0 {
		shallow, shallowErr := loadShallowHashes(ctx, repoPath)
		if shallowErr != nil {
			return plumbing.ZeroHash, false, fmt.Errorf("load shallow boundaries: %w", shallowErr)
		}
		newTip, err = cherryPickOnto(ctx, repo, remoteTip, localOnly, shallow)
		if err != nil {
			return plumbing.ZeroHash, false, fmt.Errorf("replay local checkpoints onto repaired remote: %w", err)
		}
	}

	if err := atomicSetV1Ref(ctx, repo, observedLocalTip, newTip); err != nil {
		return plumbing.ZeroHash, false, err
	}
	return newTip, true, nil
}

func hasOversizedMetadataIntroducedSince(
	ctx context.Context,
	repo *git.Repository,
	tip, boundary plumbing.Hash,
	threshold int64,
) (bool, error) {
	repoPath, err := getRepoPath(repo)
	if err != nil {
		return false, fmt.Errorf("get repository path for metadata scan: %w", err)
	}
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	rangeSpec := tip.String()
	if !boundary.IsZero() {
		rangeSpec = boundary.String() + ".." + tip.String()
	}
	cmd := exec.CommandContext(ctx, "git", "rev-list", "--topo-order", rangeSpec)
	cmd.Dir = repoPath
	out, err := cmd.Output()
	if err != nil {
		return false, fmt.Errorf("list local checkpoints after merge-base: %w", err)
	}
	hashes := strings.Fields(string(out))
	if len(hashes) > MaxCommitTraversalDepth {
		return false, fmt.Errorf("checkpoint metadata scan exceeded %d commits", MaxCommitTraversalDepth)
	}

	for _, hash := range hashes {
		if err := ctx.Err(); err != nil {
			return false, fmt.Errorf("scan local checkpoint metadata: %w", err)
		}
		commit, err := repo.CommitObject(plumbing.NewHash(hash))
		if err != nil {
			return false, fmt.Errorf("load local checkpoint commit %s: %w", hash, err)
		}
		found := false
		err = forEachMetadataBlobIntroduced(ctx, commit, func(blobPath string, hash plumbing.Hash) error {
			blob, blobErr := repo.BlobObject(hash)
			if blobErr != nil {
				return fmt.Errorf("load metadata blob %s at %s: %w", hash, blobPath, blobErr)
			}
			if blob.Size > threshold {
				found = true
			}
			return nil
		})
		if err != nil {
			return false, fmt.Errorf("inspect metadata introduced by %s: %w", commit.Hash, err)
		}
		if found {
			return true, nil
		}
	}
	return false, nil
}

