235		ctx context.Context,
236		repo *git.Repository,
237		rewrittenLocalTip, remoteTip plumbing.Hash,
238		originalToRewritten map[plumbing.Hash]plumbing.Hash,
239	) (rewritten, original plumbing.Hash, found bool, err error) {
240		remoteTrees := make(map[plumbing.Hash]struct{})
241		remoteHistory, err := repo.Log(&git.LogOptions{From: remoteTip})
242		if err != nil {
243			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("log remote checkpoint history: %w", err)
244		}
245		defer remoteHistory.Close()
246		if walkErr := remoteHistory.ForEach(func(commit *object.Commit) error {
247			if err := ctx.Err(); err != nil {
248				return fmt.Errorf("scan remote checkpoint trees: %w", err)
249			}
