251			return nil
252		}); walkErr != nil {
253			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("walk remote checkpoint history: %w", walkErr)
254		}
255	
256		rewrittenToOriginal := make(map[plumbing.Hash]plumbing.Hash, len(originalToRewritten))
257		for oldHash, newHash := range originalToRewritten {
258			rewrittenToOriginal[newHash] = oldHash
259		}
260		localHistory, err := repo.Log(&git.LogOptions{From: rewrittenLocalTip})
261		if err != nil {
262			return plumbing.ZeroHash, plumbing.ZeroHash, false, fmt.Errorf("log rewritten local checkpoint history: %w", err)
263		}
264		defer localHistory.Close()
265		walkErr := localHistory.ForEach(func(commit *object.Commit) error {
266			if err := ctx.Err(); err != nil {
267				return fmt.Errorf("scan rewritten local checkpoint trees: %w", err)
268			}
269			if _, exists := remoteTrees[commit.TreeHash]; !exists {
270				return nil
271			}
272			oldHash, exists := rewrittenToOriginal[commit.Hash]
273			if !exists {
274				return fmt.Errorf("rewritten commit %s has no original", commit.Hash)
275			}
276			rewritten = commit.Hash
277			original = oldHash
278			found = true
279			return errStop
