   179		ctx context.Context,
   180		repo *git.Repository,
   181		tip, boundary plumbing.Hash,
   182		threshold int64,
   183	) (bool, error) {
   184		repoPath, err := getRepoPath(repo)
   185		if err != nil {
   186			return false, fmt.Errorf("get repository path for metadata scan: %w", err)
   187		}
   188		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
   189		defer cancel()
   190	
   191		rangeSpec := tip.String()
   192		if !boundary.IsZero() {
   193			rangeSpec = boundary.String() + ".." + tip.String()
   194		}
   195		countCmd := exec.CommandContext(ctx, "git", "rev-list", "--count", rangeSpec)
   196		countCmd.Dir = repoPath
   197		countOut, err := countCmd.Output()
   198		if err != nil {
   199			return false, fmt.Errorf("count local checkpoints after merge-base: %w", err)
   200		}
   201		count, err := strconv.Atoi(strings.TrimSpace(string(countOut)))
   202		if err != nil {
   203			return false, fmt.Errorf("parse checkpoint history length: %w", err)
   204		}
   205		if count > MaxCommitTraversalDepth {
   206			return false, fmt.Errorf("checkpoint metadata scan exceeded %d commits", MaxCommitTraversalDepth)
   207		}
   208	
   209		objectsCmd := exec.CommandContext(ctx, "git", "rev-list", "--objects", rangeSpec)
   210		objectsCmd.Dir = repoPath
   211		objectsOut, err := objectsCmd.Output()
   212		if err != nil {
   213			return false, fmt.Errorf("list local checkpoint metadata objects: %w", err)
   214		}
   215		seen := make(map[plumbing.Hash]struct{})
   216		for _, line := range strings.Split(string(objectsOut), "\n") {
   217			if err := ctx.Err(); err != nil {
   218				return false, fmt.Errorf("scan local checkpoint metadata: %w", err)
   219			}
   220			fields := strings.SplitN(line, " ", 2)
   221			if len(fields) != 2 || path.Base(fields[1]) != paths.MetadataFileName {
   222				continue
   223			}
   224			hash := plumbing.NewHash(fields[0])
   225			if _, exists := seen[hash]; exists {
   226				continue
   227			}
   228			seen[hash] = struct{}{}
   229			blob, err := repo.BlobObject(hash)
   230			if err != nil {
   231				return false, fmt.Errorf("load metadata blob %s at %s: %w", hash, fields[1], err)
   232			}
   233			if blob.Size > threshold {
   234				return true, nil
   235			}
   236		}
   237		return false, nil
   238	}
